"""Build the speed roadmap's page in the house style.

Usage: python3.13 build-page.py ROADMAP.md HOUSE_PAGE.html OUT.html COMMIT

Each `## ` section becomes a section with a Select button; each block that
starts with a bold lead (`**Word.**`) becomes an item with its own button.
Parentheticals made only of citations leave the items and go into the
section's references at its bottom, numbered by item, so that Speak skips them.
Section 1 keeps its own "References." block, moved into the sources.
"""
import html
import re
import sys

import markdown

src, house, out, commit = sys.argv[1:5]
text = open(src, encoding="utf-8").read()
text = re.sub(r"<!--.*?-->\s*", "", text, count=1, flags=re.S)
style = open(house, encoding="utf-8").read()
head_css = style[style.index("<link rel=\"preconnect\""):style.index("</style>") + len("</style>")]

CIT_TOKEN = re.compile(
    r"`[^`]*`|F-\d+|P-\d+|Q\d+|rows? \d+(?:(?:,| and| to) \d+)*|items? \d+|"
    r"[A-Z][A-Z0-9]{0,3}(?: Q\d+)? ?§ ?[\w.()]+(?: S\d+(?: to S\d+)?)?|"
    r"[A-Z][A-Z0-9]{0,3}:\d+(?:-\d+)?(?:, ?:\d+(?:-\d+)?)*|:\d+(?:-\d+)?|"
    r"\b(?:JB|PC|AW|AD|TW|PF|PR|HC|C4P|FA|M|C|B)\b(?: Q\d+)?|"
    r"PLAN(?:\.md:\d+)?|phase \d|M\d+|S\d+|Way \d+\w?|way \w+|"
    r"[\w./-]+\.(?:fss|fsi|java|scala|tex|md|sh)(?::\d+(?:-\d+)?)?|\d+(?:-\d+)?")
FILLER = {"and", "to", "of", "the", "its", "section", "sections", "item",
          "items", "line", "lines", "by", "see", "at", "in", "on", "with",
          "plain", "column", "reading", "read", "fixed", "c", "s"}


def is_citation(inner):
    rest = CIT_TOKEN.sub(" ", inner)
    words = [w for w in re.findall(r"[A-Za-z']+", rest) if w.lower() not in FILLER]
    return len(words) <= 1 and CIT_TOKEN.search(inner) is not None


def pull_citations(block):
    """Remove citation-only parentheticals outside code spans; return (text, cites)."""
    cites = []
    parts = re.split(r"(`[^`]*`)", block)
    outp = []
    for p in parts:
        if p.startswith("`"):
            outp.append(p)
            continue

        def repl(m):
            inner = m.group(1)
            if is_citation(inner):
                cites.append(inner.strip())
                return ""
            return m.group(0)
        prev = None
        while prev != p:
            prev = p
            p = re.sub(r" ?\(([^()]*(?:\([^()]*\)[^()]*)*)\)", repl, p)
        outp.append(p)
    # Rejoin, then put back code spans that were inside removed parentheticals:
    # a parenthetical spanning a code span is split across parts, so retry on the whole.
    joined = "".join(outp)

    def repl2(m):
        inner = m.group(1)
        if "`" in inner and is_citation(inner):
            cites.append(inner.strip())
            return ""
        return m.group(0)
    joined = re.sub(r" ?\(([^()]*`[^`]*`[^()]*)\)", repl2, joined)
    joined = re.sub(r" +([.,;:])", r"\1", joined)
    return joined, cites


def md(s):
    return markdown.markdown(s, extensions=["sane_lists"])


m = re.match(r"# (.+)\n", text)
title = m.group(1).strip()
body = text[m.end():]
sections = re.split(r"^## ", body, flags=re.M)[1:]

nav, secs = [], []
for i, sec in enumerate(sections, 1):
    heading, _, rest = sec.partition("\n")
    num, _, name = heading.partition(". ")
    sid = f"s{num}"
    nav.append(f'<li><a href="#{sid}">{html.escape(name)}</a></li>')
    blocks = re.split(r"\n(?=\*\*[^*\n]+\*\*)", "\n" + rest.strip("\n"))
    intro, items = "", []
    for b in blocks:
        b = b.strip("\n")
        if not b:
            continue
        if b.startswith("**"):
            items.append(b)
        elif not items:
            intro = b
        else:
            items[-1] += "\n" + b
    refs_html = ""
    item_html = []
    if num == "1":
        own = [x for x in items if x.startswith("**References.**")]
        items = [x for x in items if not x.startswith("**References.**")]
        if own:
            refs_html = md(own[0].replace("**References.**", "", 1))
        for it in items:
            item_html.append(f'<div class="item">{md(it)}</div>')
        intro_html = md(intro) if intro else ""
    else:
        intro_txt, intro_c = pull_citations(intro) if intro else ("", [])
        intro_html = md(intro_txt) if intro_txt else ""
        refs = []
        if intro_c:
            refs.append(("Opening", intro_c))
        for it in items:
            lead = re.match(r"\*\*([^*]+)\*\*", it).group(1).rstrip(".")
            t, c = pull_citations(it)
            item_html.append(f'<div class="item">{md(t)}</div>')
            if c:
                refs.append((lead, c))
        if refs:
            lis = "".join(
                f"<li>{html.escape(lead)}: " + "; ".join(md(c)[3:-4] for c in cs) + "</li>"
                for lead, cs in refs)
            refs_html = f"<ol>{lis}</ol>"
    sources = (f'<div class="sources"><span class="label">References</span>{refs_html}</div>'
               if refs_html else "")
    secs.append(
        f'<section id="{sid}" class="part">\n<h2><span class="num">{num}</span>'
        f'{html.escape(name)}</h2>\n{intro_html}\n' + "\n".join(item_html) +
        f"\n{sources}\n</section>")

desc = ("The roadmap from today's compiled path to a fast compiled microGPT, trained in "
        "batches on several cores with SIMD kernels and float on JDK 25 and then on "
        "Valhalla, written on 2026-11-20 at the curator's request.")
page = f"""<title>Speed Roadmap</title>
<meta name="claude:viewport-fit-sides" content="cover">
<meta name="description" content="{html.escape(desc)}">
{head_css}
<style>
.item {{ min-width: 0; }}
.item > p:first-child {{ margin-top: .9rem; }}
</style>

<div class="page">
<header class="masthead">
<p class="eyebrow">Fortress revival &middot; a plan for the curator &middot; 20 November 2026</p>
<h1>{html.escape(title)}</h1>
<p class="standfirst">You asked for long-range planning on making compiled microGPT fast: fast matrix products with no external BLAS, parallel tasks, SIMD, float, JDK 25 and then Valhalla, with microGPT trained in batches on several cores at relaxed precision. Section 1 is the whole plan in short. The sections after it give each stage in detail.</p>
</header>

<nav class="parts" aria-label="Sections">
<h2>Sections</h2>
<ol>{''.join(nav)}</ol>
</nav>

{chr(10).join(secs)}

<footer class="colophon">
<p>Written on 20 November 2026 for the curator by an Opus writer, from three read-only readers' files and his handover, then checked at its sources by a fresh Opus reader, whose findings the writer took. Nothing was built, run or timed for it. The text in the repository: <code>explorations/reviews/speed-roadmap-2026-11-20.md</code>, at <code>main</code> <code>{commit}</code>, its evidence in the folder beside it.</p>
</footer>
</div>

<script>
function selectRange(r) {{
  var sel = window.getSelection();
  sel.removeAllRanges();
  sel.addRange(r);
}}
function addButton(anchor, label, fill) {{
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'sel';
  b.setAttribute('aria-label', label);
  anchor.appendChild(b);
  b.addEventListener('click', function (e) {{
    e.preventDefault();
    var r = document.createRange();
    fill(r);
    selectRange(r);
  }});
}}
document.querySelectorAll('section.part').forEach(function (sec) {{
  var h = sec.querySelector(':scope > h2');
  if (!h) return;
  addButton(h, 'Select this section to have it read aloud', function (r) {{
    r.setStart(h, 0);
    var src = sec.querySelector(':scope > .sources');
    if (src) r.setEndBefore(src); else r.setEnd(sec, sec.childNodes.length);
  }});
  sec.querySelectorAll(':scope > .item').forEach(function (it) {{
    var first = it.firstElementChild;
    if (!first) return;
    addButton(first, 'Select this item to have it read aloud', function (r) {{
      r.selectNodeContents(it);
    }});
  }});
}});
</script>
"""
open(out, "w", encoding="utf-8").write(page)
print(len(page), "bytes;", len(secs), "sections")

