"""Build the speed roadmap's page in the house style.

Usage: python3.13 build-page.py ROADMAP.md HOUSE_PAGE.html OUT.html COMMIT

Each `## ` section becomes a section with a Select button; each block that
starts with a bold lead (`**Word.**`) becomes an item with its own button.
Parentheticals made only of citations leave the items and go into the
section's references at its bottom, numbered by item, so that Speak skips them.
Section 1 keeps its own "References." block, moved into the sources.
"""
import html
import re
import sys

import markdown

src, house, out, commit = sys.argv[1:5]
text = open(src, encoding="utf-8").read()
text = re.sub(r"<!--.*?-->\s*", "", text, count=1, flags=re.S)
style = open(house, encoding="utf-8").read()
head_css = style[style.index("<link rel=\"preconnect\""):style.index("</style>") + len("</style>")]

CIT_TOKEN = re.compile(
    r"`[^`]*`|F-\d+|P-\d+|Q\d+|rows? \d+(?:(?:,| and| to) \d+)*|items? \d+|"
    r"[A-Z][A-Z0-9]{0,3}(?: Q\d+)? ?§ ?[\w.()]+(?: S\d+(?: to S\d+)?)?|"
    r"[A-Z][A-Z0-9]{0,3}:\d+(?:-\d+)?(?:, ?:\d+(?:-\d+)?)*|:\d+(?:-\d+)?|"
    r"\b(?:JB|PC|AW|AD|TW|PF|PR|HC|C4P|FA|M|C|B)\b(?: Q\d+)?|"
    r"PLAN(?:\.md:\d+)?|phase \d|M\d+|S\d+|Way \d+\w?|way \w+|"
    r"[\w./-]+\.(?:fss|fsi|java|scala|tex|md|sh)(?::\d+(?:-\d+)?)?|\d+(?:-\d+)?")
FILLER = {"and", "to", "of", "the", "its", "section", "sections", "item",
          "items", "line", "lines", "by", "see", "at", "in", "on", "with",
          "plain", "column", "reading", "read", "fixed", "c", "s"}


def is_citation(inner):
    rest = CIT_TOKEN.sub(" ", inner)
    words = [w for w in re.findall(r"[A-Za-z']+", rest) if w.lower() not in FILLER]
    return len(words) <= 1 and CIT_TOKEN.search(inner) is not None


def pull_citations(block):
    """Remove citation-only parentheticals outside code spans; return (text, cites)."""
    cites = []
    parts = re.split(r"(`[^`]*`)", block)
    outp = []
    for p in parts:
        if p.startswith("`"):
            outp.append(p)
            continue

        def repl(m):
            inner = m.group(1)
            if is_citation(inner):
                cites.append(inner.strip())
                return ""
            return m.group(0)
        prev = None
        while prev != p:
            prev = p
            p = re.sub(r" ?\(([^()]*(?:\([^()]*\)[^()]*)*)\)", repl, p)
        outp.append(p)
    # Rejoin, then put back code spans that were inside removed parentheticals:
    # a parenthetical spanning a code span is split across parts, so retry on the whole.
    joined = "".join(outp)

    def repl2(m):
        inner = m.group(1)
        if "`" in inner and is_citation(inner):
            cites.append(inner.strip())
            return ""
        return m.group(0)
    joined = re.sub(r" ?\(([^()]*`[^`]*`[^()]*)\)", repl2, joined)
    joined = re.sub(r" +([.,;:])", r"\1", joined)
    return joined, cites


def md(s):
    return markdown.markdown(s, extensions=["sane_lists"])


m = re.match(r"# (.+)\n", text)
title = m.group(1).strip()
body = text[m.end():]
sections = re.split(r"^## ", body, flags=re.M)[1:]

nav, secs = [], []
for i, sec in enumerate(sections, 1):
    heading, _, rest = sec.partition("\n")
    num, _, name = heading.partition(". ")
    sid = f"s{num}"
    nav.append(f'<li><a href="#{sid}">{html.escape(name)}</a></li>')
    blocks = re.split(r"\n(?=\*\*[^*\n]+\*\*)", "\n" + rest.strip("\n"))
    intro, items = "", []
    for b in blocks:
        b = b.strip("\n")
        if not b:
            continue
        if b.startswith("**"):
            items.append(b)
        elif not items:
            intro = b
        else:
            items[-1] += "\n" + b
    refs_html = ""
    item_html = []
    if num == "1":
        own = [x for x in items if x.startswith("**References.**")]
        items = [x for x in items if not x.startswith("**References.**")]
        if own:
            refs_html = md(own[0].replace("**References.**", "", 1))
        for it in items:
            item_html.append(f'<div class="item">{md(it)}</div>')
        intro_html = md(intro) if intro else ""
    else:
        intro_txt, intro_c = pull_citations(intro) if intro else ("", [])
        intro_html = md(intro_txt) if intro_txt else ""
        refs = []
        if intro_c:
            refs.append(("Opening", intro_c))
        for it in items:
            lead = re.match(r"\*\*([^*]+)\*\*", it).group(1).rstrip(".")
            t, c = pull_citations(it)
            item_html.append(f'<div class="item">{md(t)}</div>')
